/**
 * Service worker registration for the installable client.
 *
 * `virtual:pwa-register` is generated by vite-plugin-pwa at build time, so the
 * import is dynamic and failures are non-fatal — the app must still run when the
 * service worker is unavailable (unit tests, insecure origins, older browsers).
 */
import { ref } from 'vue'

export const offlineReady = ref(false)
export const needRefresh = ref(false)

let applyUpdate = null

export async function registerServiceWorker() {
  if (typeof window === 'undefined' || !('serviceWorker' in navigator)) return

  try {
    const { registerSW } = await import('virtual:pwa-register')
    applyUpdate = registerSW({
      immediate: true,
      onOfflineReady() {
        offlineReady.value = true
      },
      onNeedRefresh() {
        needRefresh.value = true
      },
    })
  } catch {
    // No service worker in this environment; the app works without it.
  }
}

/** Activate the waiting worker and reload. */
export function updateApp() {
  needRefresh.value = false
  applyUpdate?.(true)
}

export function dismissToast() {
  offlineReady.value = false
  needRefresh.value = false
}
